a:acp.a:expr:
= choose(
  if(
    or(
      a!isNullOrEmpty(pv!opcion),
      pv!opcion > 1,
      pv!opcion < 1
    ),
    2,
    pv!opcion
  ),
  "REINTENTAR",
  "ACCION NO RECONOCIDA",
)

uiExpressionForm.expression:
=/*41707069616E-GEN-DEBUG*/=a!formLayout(
  buttons: a!buttonLayout(
    primaryButtons: {
      a!buttonWidgetSubmit(
        label: "OK",
        style: "PRIMARY"
      )
    }
  ))

